def main():
    out = []
    for (tid, en, pt, year, genres, (did, dname), budget, revenue, rt, (noms, wins, bp), roles, flags, hard, medium, extra) in F:
        rs = []
        for (actor, order, gender, oscar, razzie) in roles:
            rs.append({"actor": actor, "order": order, "gender": gender, "demand": role_demand(genres, oscar != "none"), "oscar": oscar, "razzie": razzie})
        rec = {
            "tmdb_id": tid, "imdb_id": None, "title": {"original": en, "en": en, "pt": pt}, "year": year, "genres": genres,
            "director": {"tmdb_id": did, "name": dname}, "roles": rs, "budget": int(budget), "revenue": int(revenue), "rt": rt,
            "metacritic": None, "film_awards": {"oscar_nominations": noms, "oscar_wins": wins, "best_picture": bp, "palme_dor": tid in (680, 1064213), "razzie_nominations": 1 if tid == 694 else 0},
            "poster": None, "blind": {"hard": hard, "medium": medium}, "flags": flags, "trivia": extra.get("trivia", []),
            "rumors": extra.get("rumors", []), "revision": extra.get("revision"), "refused_by": extra.get("refused_by", []),
            "franchise_id": extra.get("franchise_id"), "sample": True,
        }
        rec["derived"] = derive(rec)
        out.append(rec)
    dst = Path(__file__).resolve().parents[2] / "game" / "src" / "data" / "films.sample.json"
    dst.write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{len(out)} filmes → {dst}")

if __name__ == "__main__":
    main()
